function Invoke-WinUtilDesktopShortcut {
    <#
    .SYNOPSIS
        Creates or removes a 1-click Desktop Shortcut for WinUtil-MAX.
    .DESCRIPTION
        Creates a desktop shortcut that launches WinUtil-MAX directly from GitHub
        with execution policy bypass, ensuring it always pulls the latest version
        without PowerShell policy restrictions. Uses an embedded Max icon stored
        locally in LocalAppData.
    #>
    [CmdletBinding()]
    param(
        [switch]$Remove
    )

    $desktopCandidates = @(
        [Environment]::GetFolderPath('Desktop'),
        (Join-Path $env:USERPROFILE 'Desktop'),
        (Join-Path $env:USERPROFILE 'OneDrive\Desktop'),
        [Environment]::GetFolderPath('CommonDesktopDirectory'),
        (Join-Path $env:PUBLIC 'Desktop')
    ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and (Test-Path -LiteralPath $_) } | Select-Object -Unique

    $iconDir = Join-Path $env:LocalAppData 'winutil-max'
    $iconFile = Join-Path $iconDir 'winutil_max.ico'

    if ($Remove) {
        Write-WinUtilLog -Component "DesktopShortcut" -Message "Removing WinUtil-MAX desktop shortcut."
        Write-Host "[winutil-MAX] [$(Get-Date -Format 'HH:mm:ss')] >> Removing desktop shortcut..." -ForegroundColor Cyan

        $removed = $false
        foreach ($dir in $desktopCandidates) {
            $candidateLnk = Join-Path $dir 'WinUtil-MAX.lnk'
            if (Test-Path -LiteralPath $candidateLnk) {
                Remove-Item -LiteralPath $candidateLnk -Force -ErrorAction SilentlyContinue
                $removed = $true
            }
        }

        # Clean legacy icon files
        @('MAX.ico', 'Ri.ico', 'winutil_max.ico') | ForEach-Object {
            $f = Join-Path $iconDir $_
            if (Test-Path -LiteralPath $f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
        }

        # Refresh Explorer icon cache
        try {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class WinUtilShellNotifierRemove {
    [DllImport("shell32.dll")]
    public static extern void SHChangeNotify(int wEventId, uint uFlags, IntPtr dwItem1, IntPtr dwItem2);
}
"@ -ErrorAction SilentlyContinue
            [WinUtilShellNotifierRemove]::SHChangeNotify(0x08000000, 0, [IntPtr]::Zero, [IntPtr]::Zero)
        } catch {}

        if ($removed) {
            Write-Host "[winutil-MAX] [SUCCESS] WinUtil-MAX desktop shortcut removed." -ForegroundColor Green
            if (Test-WinUtilUIAlive) {
                Show-WinUtilMessage -Title "Desktop Shortcut Removed" -Message "WinUtil-MAX desktop shortcut has been removed from your desktop." -Button "OK" -Icon "Information"
            }
        } else {
            Write-Host "[winutil-MAX] [INFO] No desktop shortcut was found to remove." -ForegroundColor Yellow
            if (Test-WinUtilUIAlive) {
                Show-WinUtilMessage -Title "Desktop Shortcut" -Message "No WinUtil-MAX shortcut was found on your desktop." -Button "OK" -Icon "Information"
            }
        }
        return
    }

    Write-WinUtilLog -Component "DesktopShortcut" -Message "Creating WinUtil-MAX desktop shortcut."
    Write-Host "[winutil-MAX] [$(Get-Date -Format 'HH:mm:ss')] >> Creating WinUtil-MAX desktop shortcut..." -ForegroundColor Cyan

    try {
        if (-not (Test-Path -LiteralPath $iconDir)) {
            New-Item -Path $iconDir -ItemType Directory -Force | Out-Null
        }

        # Clean old cached icon files so Explorer does not pull legacy avatar icons
        @('MAX.ico', 'Ri.ico') | ForEach-Object {
            $legacy = Join-Path $iconDir $_
            if (Test-Path -LiteralPath $legacy) { Remove-Item -LiteralPath $legacy -Force -ErrorAction SilentlyContinue }
        }

        # Check local assets first, otherwise extract embedded base64 icon
        $localIco = $null
        if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) {
            $candidate = Join-Path $PSScriptRoot '..\..\assets\winutil_max.ico'
            if (Test-Path -LiteralPath $candidate) { $localIco = (Resolve-Path -LiteralPath $candidate).Path }
        }
        if (-not $localIco -and (Test-Path -LiteralPath '.\assets\winutil_max.ico')) {
            $localIco = (Resolve-Path -LiteralPath '.\assets\winutil_max.ico').Path
        }

        if ($localIco) {
            Copy-Item -LiteralPath $localIco -Destination $iconFile -Force -ErrorAction SilentlyContinue
        } else {
            $base64 = ''
            [System.IO.File]::WriteAllBytes($iconFile, [Convert]::FromBase64String($base64))
        }

        # Resolve primary desktop path
        $desktopPath = [Environment]::GetFolderPath('Desktop')
        if (-not $desktopPath -or -not (Test-Path -LiteralPath $desktopPath)) {
            $desktopPath = Join-Path $env:USERPROFILE 'Desktop'
        }
        $shortcutPath = Join-Path $desktopPath 'WinUtil-MAX.lnk'

        # Create shortcut via WScript.Shell
        $wshShell = New-Object -ComObject WScript.Shell
        $shortcut = $wshShell.CreateShortcut($shortcutPath)
        $shortcut.TargetPath = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
        $shortcut.Arguments = '-NoProfile -ExecutionPolicy Bypass -Command "& ([ScriptBlock]::Create((irm https://raw.githubusercontent.com/R-Rinku/winutil-max/main/winutil.ps1)))"'
        $shortcut.Description = "⚡ WinUtil-MAX - The Ultimate Windows Optimization, Automation & Tweaking Suite"
        $shortcut.WorkingDirectory = "$env:USERPROFILE"
        if (Test-Path -LiteralPath $iconFile) {
            $shortcut.IconLocation = "$iconFile,0"
        }
        $shortcut.Save()

        # If user has OneDrive Desktop, ensure it is mirrored or created there too
        $oneDriveDesktop = Join-Path $env:USERPROFILE 'OneDrive\Desktop'
        if ((Test-Path -LiteralPath $oneDriveDesktop) -and ($oneDriveDesktop -ne $desktopPath)) {
            $odShortcutPath = Join-Path $oneDriveDesktop 'WinUtil-MAX.lnk'
            $odShortcut = $wshShell.CreateShortcut($odShortcutPath)
            $odShortcut.TargetPath = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
            $odShortcut.Arguments = '-NoProfile -ExecutionPolicy Bypass -Command "& ([ScriptBlock]::Create((irm https://raw.githubusercontent.com/R-Rinku/winutil-max/main/winutil.ps1)))"'
            $odShortcut.Description = "⚡ WinUtil-MAX - The Ultimate Windows Optimization, Automation & Tweaking Suite"
            $odShortcut.WorkingDirectory = "$env:USERPROFILE"
            if (Test-Path -LiteralPath $iconFile) {
                $odShortcut.IconLocation = "$iconFile,0"
            }
            $odShortcut.Save()
        }

        # Refresh Windows Explorer shell icon cache immediately
        try {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class WinUtilShellNotifierCreate {
    [DllImport("shell32.dll")]
    public static extern void SHChangeNotify(int wEventId, uint uFlags, IntPtr dwItem1, IntPtr dwItem2);
}
"@ -ErrorAction SilentlyContinue
            [WinUtilShellNotifierCreate]::SHChangeNotify(0x08000000, 0, [IntPtr]::Zero, [IntPtr]::Zero)
        } catch {}

        Write-Host "[winutil-MAX] [SUCCESS] WinUtil-MAX desktop shortcut created at: $shortcutPath" -ForegroundColor Green
        Write-WinUtilLog -Component "DesktopShortcut" -Message "Desktop shortcut created at $shortcutPath."

        if (Test-WinUtilUIAlive) {
            $msg = "WinUtil-MAX Desktop Shortcut has been created successfully!`n`n" +
                   "Location:`n$shortcutPath`n`n" +
                   "Features:`n" +
                   "• Always pulls the latest updates directly from GitHub`n" +
                   "• Launches with ExecutionPolicy Bypass (no script restrictions)`n" +
                   "• Features the official Max Mayfield icon`n`n" +
                   "You can now launch WinUtil-MAX with a single click from your Desktop!"
            Show-WinUtilMessage -Title "Desktop Shortcut Created" -Message $msg -Button "OK" -Icon "Information"
        }
    } catch {
        Write-WinUtilLog -Level "ERROR" -Component "DesktopShortcut" -Message "Failed to create desktop shortcut: $_"
        Write-Host "[winutil-MAX] [ERROR] Failed to create desktop shortcut: $_" -ForegroundColor Red
        if (Test-WinUtilUIAlive) {
            Show-WinUtilMessage -Title "Shortcut Error" -Message "Failed to create desktop shortcut: $_" -Button "OK" -Icon "Error"
        }
    }
}
